package pzvrphysicality;

import java.nio.file.*;import java.util.*;import java.util.zip.ZipFile;import java.security.MessageDigest;
import org.lwjgl.opengl.GL;import static org.lwjgl.glfw.GLFW.*;import static org.lwjgl.opengl.GL33.*;
import viewpointvr.physics.PackedModelGeometry;

/** Executes the pinned native shader function as data in an owned hidden GL context, without loading Viewpoint classes. */
public final class PackCurtainGpuTest {
 private static int checks;private static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}
 private static int shader(int type,String source){int s=glCreateShader(type);glShaderSource(s,source);glCompileShader(s);if(glGetShaderi(s,GL_COMPILE_STATUS)==0)throw new AssertionError(glGetShaderInfoLog(s));return s;}
 private static int bufferTexture(int unit,int format,float[] values){int b=glGenBuffers(),t=glGenTextures();glBindBuffer(GL_TEXTURE_BUFFER,b);glBufferData(GL_TEXTURE_BUFFER,values,GL_STATIC_DRAW);glActiveTexture(GL_TEXTURE0+unit);glBindTexture(GL_TEXTURE_BUFFER,t);glTexBuffer(GL_TEXTURE_BUFFER,format,b);glDeleteBuffers(b);return t;}
 private static void uniform(int program,String name,int value){int location=glGetUniformLocation(program,name);if(location>=0)glUniform1i(location,value);}
 public static void main(String[] args)throws Exception{
  Path output=Path.of(args[0]);Files.createDirectories(output);byte[] nativeShader;try(var jar=new ZipFile(args[1])){try(var stream=jar.getInputStream(jar.getEntry("viewpoint/shaders/lib/pack_model.glsl"))){nativeShader=stream.readAllBytes();}}
  String nativeCode=new String(nativeShader,java.nio.charset.StandardCharsets.UTF_8).replaceAll("(?m)^#include.*$","");String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(nativeShader));
  // This fixture supplies numeric slot selectors. The complete original modelVertex function is unchanged.
  String vertex="#version 330\nuniform samplerBuffer uPlantSlots;const int PLANT_TEXELS=5,MODEL_SQUARE=6,MODEL_INDEX=7,MODEL_FLAGS=8,NO_SQUARE=64,FLAG_SINGLE_SIDED=2;\n"+nativeCode+"\nlayout(location=0) in vec3 inputPosition;out vec3 mapped;out float hidden;void main(){ModelVertex v=modelVertex(inputPosition,vec2(0),vec3(0,0,1));mapped=vec3(-v.pos.x,-v.pos.z,v.pos.y);hidden=v.hidden?1:0;gl_Position=vec4(0);}";
  check(glfwInit(),"own GLFW initialized");glfwWindowHint(GLFW_VISIBLE,GLFW_FALSE);glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR,3);glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR,3);glfwWindowHint(GLFW_OPENGL_PROFILE,GLFW_OPENGL_COMPAT_PROFILE);long window=glfwCreateWindow(32,32,"Curtain numeric contract",0,0);if(window==0)throw new IllegalStateException("Own hidden GL unavailable");
  try{glfwMakeContextCurrent(window);GL.createCapabilities();int vs=shader(GL_VERTEX_SHADER,vertex),fs=shader(GL_FRAGMENT_SHADER,"#version 330\nout vec4 color;void main(){color=vec4(1);}");int program=glCreateProgram();glAttachShader(program,vs);glAttachShader(program,fs);glTransformFeedbackVaryings(program,new CharSequence[]{"mapped","hidden"},GL_INTERLEAVED_ATTRIBS);glLinkProgram(program);check(glGetProgrami(program,GL_LINK_STATUS)!=0,"actual native pack function compiles and links");glDeleteShader(vs);glDeleteShader(fs);glUseProgram(program);uniform(program,"uPlantSlots",0);uniform(program,"uPackTable",1);uniform(program,"uMeshRecords",2);
   float[] positions={-.4f,.5f,-.03f,.5f,.5f,.02f,.4f,1.8f,.01f,-.5f,1.8f,-.02f};var mesh=new PackedModelGeometry.Mesh(positions,new int[]{0,1,2,0,2,3});int vao=glGenVertexArrays();glBindVertexArray(vao);int input=glGenBuffers();glBindBuffer(GL_ARRAY_BUFFER,input);glBufferData(GL_ARRAY_BUFFER,positions,GL_STATIC_DRAW);glEnableVertexAttribArray(0);glVertexAttribPointer(0,3,GL_FLOAT,false,12,0L);int feedback=glGenBuffers();glBindBuffer(GL_TRANSFORM_FEEDBACK_BUFFER,feedback);glBufferData(GL_TRANSFORM_FEEDBACK_BUFFER,64,GL_STREAM_READ);glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER,0,feedback);
   int art=bufferTexture(1,GL_RGBA32F,new float[]{0,0,1,1,0,0,1,1}),record=bufferTexture(2,GL_RGBA32F,new float[12]);glEnable(GL_RASTERIZER_DISCARD);
   for(float[] pose:new float[][]{{1,0,1},{0,1,1},{-1,0,.75f},{.6f,.8f,1.25f}})for(int square:new int[]{17,31,43,63})for(boolean visible:new boolean[]{false,true}){
    var expected=MeshPlacement.place(mesh,pose[0],pose[1],pose[2]).vertices();float[] slots={0,0,0,pose[0],pose[1],pose[2],Float.intBitsToFloat(square),Float.intBitsToFloat(0),0,0};int model=bufferTexture(0,GL_RG32F,slots);glVertexAttribI4i(9,0,0,square<32&&visible?1<<square:0,square>=32&&visible?1<<(square-32):0);glBeginTransformFeedback(GL_POINTS);glDrawArrays(GL_POINTS,0,4);glEndTransformFeedback();float[] actual=new float[16];glBindBuffer(GL_TRANSFORM_FEEDBACK_BUFFER,feedback);glGetBufferSubData(GL_TRANSFORM_FEEDBACK_BUFFER,0,actual);boolean equal=true,mask=true;for(int n=0;n<4;n++){for(int axis=0;axis<3;axis++)equal&=Math.abs(actual[n*4+axis]-expected[n*3+axis])<.00001f;mask&=actual[n*4+3]==(visible?0:1);}check(equal,"native shader transform matches copied collision coordinates, rotation/scale="+Arrays.toString(pose));check(mask,"native square word and bit agree with admission for square="+square+", visible="+visible);glDeleteTextures(model);
   }
   glDisable(GL_RASTERIZER_DISCARD);glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER,0,0);glBindVertexArray(0);glUseProgram(0);glDeleteBuffers(input);glDeleteBuffers(feedback);glDeleteVertexArrays(vao);glDeleteProgram(program);glDeleteTextures(art);glDeleteTextures(record);check(glGetError()==GL_NO_ERROR,"all owned GL resources close without errors");Files.writeString(output.resolve("readback.json"),"{\"Passed\":true,\"Checks\":"+checks+",\"NativeShaderSha256\":\""+hash+"\",\"OriginalJavaMethodsExecuted\":false,\"GameExecuted\":false,\"HeadsetVerified\":false,\"PixelAppearanceVerified\":false,\"NumericTransformFeedback\":true}\n");System.out.println("Pack curtain GPU: "+checks+" shader transform and mask checks passed");
  }finally{glfwMakeContextCurrent(0);GL.setCapabilities(null);glfwDestroyWindow(window);glfwTerminate();}
 }
 private PackCurtainGpuTest(){}
}
